#include <vector>
using namespace std;

vector<int> c0(1, 0), c1(1, 0), cnt(1, 0);

void insertValue(long long x) {
    int v = 0;
    for (int b = 30; b >= 0; b--) {
        vector<int>& next = ((x >> b) & 1) ? c1 : c0;
        if (!next[v]) {
            c0.push_back(0);
            c1.push_back(0);
            cnt.push_back(0);
            next[v] = (int)c0.size() - 1;
        }
        v = next[v];
        cnt[v]++;
    }
}

long long lessCount(long long a, long long x) {
    int v = 0;
    long long res = 0;
    for (int b = 30; b >= 0; b--) {
        int same, diff;
        if ((a >> b) & 1) {
            same = c1[v];
            diff = c0[v];
        } else {
            same = c0[v];
            diff = c1[v];
        }
        if ((x >> b) & 1) {
            if (same) res += cnt[same];
            v = diff;
        } else {
            v = same;
        }
        if (!v) break;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
