import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] c0, c1, cnt;
    static int nodes;

    static void insertValue(long x) {
        int v = 0;
        for (int b = 30; b >= 0; b--) {
            if (((x >> b) & 1L) != 0) {
                if (c1[v] == 0) c1[v] = ++nodes;
                v = c1[v];
            } else {
                if (c0[v] == 0) c0[v] = ++nodes;
                v = c0[v];
            }
            cnt[v]++;
        }
    }

    static long lessCount(long a, long x) {
        int v = 0;
        long res = 0;
        for (int b = 30; b >= 0; b--) {
            int same, diff;
            if (((a >> b) & 1L) != 0) {
                same = c1[v];
                diff = c0[v];
            } else {
                same = c0[v];
                diff = c1[v];
            }
            if (((x >> b) & 1L) != 0) {
                if (same != 0) res += cnt[same];
                v = diff;
            } else {
                v = same;
            }
            if (v == 0) break;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long lo = Long.parseLong(next());
        long hi = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cn = (int) n;
        c0 = new int[31 * (cn + 1) + 5];
        c1 = new int[31 * (cn + 1) + 5];
        cnt = new int[31 * (cn + 1) + 5];
        nodes = 0;
        long total = 0;
        for (int i = 0; i < cn; i++) {
            total += lessCount(a[i], hi + 1) - lessCount(a[i], lo);
            insertValue(a[i]);
        }
        System.out.println(total);
    }
}
